.version 7.0
.target sm_80
.address_size 64

.visible .entry conv1d_fp16(
    .param .u64 input_ptr,
    .param .u64 weight_ptr,
    .param .u64 output_ptr,
    .param .u32 batch,
    .param .u32 cin,
    .param .u32 cout,
    .param .u32 lin,
    .param .u32 ksize
)
{
    // ----- registers -------------------------------------------------------
    .reg .u64 %in_ptr, %w_ptr, %out_ptr;
    .reg .u32 %batch, %cin, %cout, %lin, %ksize, %lout;
    .reg .u32 %gid, %total;
    .reg .u32 %pos, %tmp, %oc, %n;
    .reg .u64 %base_in, %base_out, %out_addr;
    .reg .u64 %tmp64;
    .reg .u32 %ic, %k;
    .reg .pred %p_done;
    .reg .f32 %acc;
    .reg .f16 %val_in, %val_w, %out_half;
    .reg .f32 %val_in_f32, %val_w_f32;
    .reg .u64 %w_off;

    // ----- load parameters -------------------------------------------------
    ld.param.u64 %in_ptr,   [input_ptr];
    ld.param.u64 %w_ptr,    [weight_ptr];
    ld.param.u64 %out_ptr,  [output_ptr];
    ld.param.u32 %batch,    [batch];
    ld.param.u32 %cin,      [cin];
    ld.param.u32 %cout,     [cout];
    ld.param.u32 %lin,      [lin];
    ld.param.u32 %ksize,    [ksize];

    // lout = lin - ksize + 1
    sub.u32 %lout, %lin, %ksize;
    add.u32 %lout, %lout, 1;

    // global thread id
    mov.u32 %gid, %tid.x;
    mov.u32 %tmp, %ctaid.x;
    mad.lo.u32 %gid, %tmp, %ntid.x, %gid;   // gid = blockIdx.x * blockDim.x + threadIdx.x

    // total = batch * cout * lout
    mul.lo.u32 %tmp, %batch, %cout;
    mul.lo.u32 %total, %tmp, %lout;

    // if gid >= total -> exit
    setp.ge.u32 %p_done, %gid, %total;
    @%p_done ret;

    // decompose gid -> (n, oc, pos)
    rem.u32 %pos, %gid, %lout;
    div.u32 %tmp, %gid, %lout;
    rem.u32 %oc, %tmp, %cout;
    div.u32 %n, %tmp, %cout;

    // base_in = in_ptr + n * cin * lin * 2
    mul.lo.u64 %tmp64, %n, %cin;
    mul.lo.u64 %tmp64, %tmp64, %lin;
    mul.wide.u32 %tmp64, %tmp64, 2;
    add.u64 %base_in, %in_ptr, %tmp64;

    // base_out = out_ptr + n * cout * lout * 2
    mul.lo.u64 %tmp64, %n, %cout;
    mul.lo.u64 %tmp64, %tmp64, %lout;
    mul.wide.u32 %tmp64, %tmp64, 2;
    add.u64 %base_out, %out_ptr, %tmp64;

    // out address = base_out + (oc * lout + pos) * 2
    mul.lo.u64 %tmp64, %oc, %lout;
    add.u64 %tmp64, %tmp64, %pos;
    mul.wide.u32 %tmp64, %tmp64, 2;
    add.u64 %out_addr, %base_out, %tmp64;

    // accumulator (fp32)
    mov.f32 %acc, 0f00000000;

    // ----- outer loop over input channels ---------------------------------
    mov.u32 %ic, 0;
OUTER_LOOP:
    setp.ge.u32 %p_done, %ic, %cin;
    @%p_done bra AFTER_OUTER;

    // ----- inner loop over kernel elements --------------------------------
    mov.u32 %k, 0;
INNER_LOOP:
    setp.ge.u32 %p_done, %k, %ksize;
    @%p_done bra END_INNER;

    // ---- load input element (fp16) ---------------------------------------
    // idx_in = ic * lin + pos + k
    mul.lo.u64 %tmp64, %ic, %lin;
    add.u64 %tmp64, %tmp64, %pos;
    add.u64 %tmp64, %tmp64, %k;
    mul.wide.u32 %tmp64, %tmp64, 2;
    add.u64 %tmp64, %base_in, %tmp64;          // address of input element
    ld.global.u16 %val_in, [%tmp64];
    cvt.f32.f16 %val_in_f32, %val_in;

    // ---- load weight element (fp16) ---------------------------------------
    // idx_w = oc * cin * ksize + ic * ksize + k
    mul.lo.u64 %w_off, %oc, %cin;
    mul.lo.u64 %w_off, %w_off, %ksize;        // oc * cin * ksize
    mul.lo.u64 %tmp64, %ic, %ksize;           // ic * ksize
    add.u64 %w_off, %w_off, %tmp64;
    add.u64 %w_off, %w_off, %k;
    mul.wide.u32 %w_off, %w_off, 2;
    add.u64 %w_off, %w_ptr, %w_off;
    ld.global.u16 %val_w, [%w_off];
    cvt.f32.f16 %val_w_f32, %val_w;

    // ---- accumulate --------------------------------------------------------
    fma.rn.f32 %acc, %val_in_f32, %val_w_f32, %acc;

    // k++
    add.u32 %k, %k, 1;
    bra INNER_LOOP;
END_INNER:

    // ic++
    add.u32 %ic, %ic, 1;
    bra OUTER_LOOP;
AFTER_OUTER:

    // ----- write result (fp16) ---------------------------------------------
    cvt.rn.f16.f32 %out_half, %acc;
    st.global.u16 [%out_addr], %out_half;

    ret;
}
