# --------------------------------------------------------------
# Model wrapper that loads the PTX and launches the kernel.
# --------------------------------------------------------------
import torch

class ModelNew:
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int):
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size

        # weight tensor (out_channels, in_channels, kernel_size) in fp16
        self.weight = torch.randn(
            out_channels, in_channels, kernel_size,
            dtype=torch.float16, device='cuda'
        )

        # load PTX module (ptx_load & ptx_launch are provided by the harness)
        self.module = ptx_load(PTX_SOURCE)

    def __call__(self, x: torch.Tensor) -> torch.Tensor:
        """
        x: (batch, in_channels, length)  fp16 tensor on CUDA
        returns: (batch, out_channels, length_out) fp16 tensor on CUDA
        """
        batch, cin, lin = x.shape
        k = self.kernel_size
        lout = lin - k + 1

        output = torch.empty(
            batch, self.out_channels, lout,
            dtype=torch.float16, device='cuda'
        )

        total = batch * self.out_channels * lout
        block = 256
        grid = (total + block - 1) // block

        args = [
            x.data_ptr(),
            self.weight.data_ptr(),
            output.data_ptr(),
            batch,
            cin,
            self.out_channels,
            lin,
            k
        ]

        ptx_launch(self.module, "conv1d_fp16", grid, block, args)

        return output
